def largestIslandAfterEach(m, n, positions):
    parent = list(range(m * n))
    size = [1] * (m * n)
    land = [False] * (m * n)

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    best = 0
    out = []
    for r, c in positions:
        idx = r * n + c
        if not land[idx]:
            land[idx] = True
            for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                nr, nc = r + dr, c + dc
                if 0 <= nr < m and 0 <= nc < n and land[nr * n + nc]:
                    a, b = find(idx), find(nr * n + nc)
                    if a != b:
                        if size[a] < size[b]:
                            a, b = b, a
                        parent[b] = a
                        size[a] += size[b]
            best = max(best, size[find(idx)])
        out.append(best)
    return out
